196	/* White-box fixture helper: builds one node directly (bypassing rb_insert)
197	 * so test_rb_validate can wire up structurally-valid-but-invariant-violating
198	 * trees that rb_insert itself should never be able to produce. */
199	static rbnode_t *mk_node(rbtree_t *t, const char *key, int color)
200	{
201	    rbnode_t *n = rb_malloc(sizeof *n);
202	    assert(n);
203	    n->key = rb_malloc(strlen(key) + 1);
204	    assert(n->key);
205	    memcpy(n->key, key, strlen(key) + 1);
206	    n->value = NULL;
207	    n->left = n->right = n->parent = t->nil;
208	    n->color = color;
209	    return n;
210	}
211	
212	/* Every mk_node-built fixture allocates exactly node_count node structs and
213	 * node_count key buffers; rb_destroy must free all of those plus nil and the
214	 * tree struct itself -- no more (a leak) and no less (an over-free, or nil
215	 * getting freed more than once if traversal doesn't stop at the sentinel). */
216	static void destroy_and_check_frees(rbtree_t *t, int node_count)
217	{
218	    fault_malloc_arm(0);          /* never fails; just resets the free counter */
219	    rb_destroy(t);
220	    assert(fault_malloc_free_count() == node_count * 2 + 2);
221	    fault_malloc_disarm();
222	}
223	
224	/* rb_validate must enforce four invariants: BST order, red implies black
225	 * children, equal black-height on every root-to-nil path, and the root is
226	 * black. Each case below isolates exactly one of those, and every violation
227	 * gets its left/right (or shallow/deep) mirror so an implementation that
228	 * only checks one side can't pass by accident. */
229	static void test_rb_validate(void)
230	{
231	    /* Cases 1-4: red-red violation (a red node with a red child), at each
232	     * combination of which side of the root the red parent is on and which
233	     * side of that parent the red child is on. Ordering is correct and both
234	     * root-to-nil paths carry the same black count in every case, so only
235	     * the red-red rule is broken. */
236	    {
237	        static const struct {
238	            const char *name;
239	            const char *parent_key;
240	            int parent_is_left;      /* parent is root's left (1) or right (0) child */
241	            const char *child_key;
242	            int child_is_left;       /* red child is parent's left (1) or right (0) child */
243	        } cases[] = {
244	            { "validate_red_red_LL", "d", 1, "b", 1 },
245	            { "validate_red_red_LR", "d", 1, "f", 0 },
246	            { "validate_red_red_RL", "t", 0, "r", 1 },
247	            { "validate_red_red_RR", "t", 0, "v", 0 },
248	        };
249	        for (size_t i = 0; i < sizeof cases / sizeof cases[0]; i++) {
250	            rbtree_t *t = rb_create(NULL);
251	            assert(t);
252	
253	            rbnode_t *parent = mk_node(t, cases[i].parent_key, RB_RED);
254	            rbnode_t *child = mk_node(t, cases[i].child_key, RB_RED);
255	            child->parent = parent;
256	            if (cases[i].child_is_left)
257	                parent->left = child;
258	            else
259	                parent->right = child;
260	
261	            rbnode_t *root = mk_node(t, "m", RB_BLACK);
262	            root->parent = t->nil;
263	            if (cases[i].parent_is_left) {
264	                root->left = parent;
265	                root->right = t->nil;
266	            } else {
267	                root->right = parent;
268	                root->left = t->nil;
269	            }
270	            parent->parent = root;
271	            t->root = root;
272	            t->size = 3;
273	
274	            assert(rb_validate(t) != 0);
275	            destroy_and_check_frees(t, 3);
276	            printf("ok - %s\n", cases[i].name);
277	        }
278	    }
279	
280	    /* Cases 5-8: BST-order violation. The first two are immediate
281	     * parent/child inversions; the last two are deeper ancestor-bound
282	     * violations -- a node that's fine relative to its immediate parent but
283	     * violates a grandparent's bound, which a validator that only compares
284	     * a node to its direct parent (instead of threading a min/max bound)
285	     * would miss. All nodes BLACK so there's no red-red/black-height noise. */
286	    {
287	        rbtree_t *t = rb_create(NULL);
288	        assert(t);
289	        rbnode_t *root = mk_node(t, "m", RB_BLACK);
290	        rbnode_t *left = mk_node(t, "z", RB_BLACK); /* should be < "m" */
291	        root->left = left;
292	        root->right = t->nil;
293	        root->parent = t->nil;
294	        left->parent = root;
295	        t->root = root;
296	        t->size = 2;
297	        assert(rb_validate(t) != 0);
298	        destroy_and_check_frees(t, 2);
299	        printf("ok - validate_bst_order_immediate_left_too_big\n");
300	    }
301	    {
302	        rbtree_t *t = rb_create(NULL);
303	        assert(t);
304	        rbnode_t *root = mk_node(t, "m", RB_BLACK);
305	        rbnode_t *right = mk_node(t, "b", RB_BLACK); /* should be > "m" */
306	        root->right = right;
307	        root->left = t->nil;
308	        root->parent = t->nil;
309	        right->parent = root;
310	        t->root = root;
311	        t->size = 2;
312	        assert(rb_validate(t) != 0);
313	        destroy_and_check_frees(t, 2);
314	        printf("ok - validate_bst_order_immediate_right_too_small\n");
315	    }
316	    {
317	        rbtree_t *t = rb_create(NULL);
318	        assert(t);
319	        rbnode_t *root = mk_node(t, "m", RB_BLACK);
320	        rbnode_t *left = mk_node(t, "d", RB_BLACK);       /* valid: "d" < "m" */
321	        rbnode_t *deep = mk_node(t, "x", RB_BLACK);       /* valid vs "d": "x" > "d" ... */
322	        left->right = deep;                               /* ...but "x" > "m" violates root's bound */
323	        left->left = t->nil;
324	        deep->left = deep->right = t->nil;
325	        root->left = left;
326	        root->right = t->nil;
327	        root->parent = t->nil;
328	        left->parent = root;
329	        deep->parent = left;
330	        t->root = root;
331	        t->size = 3;
332	        assert(rb_validate(t) != 0);
333	        destroy_and_check_frees(t, 3);
334	        printf("ok - validate_bst_order_deep_left_exceeds_root\n");
335	    }
336	    {
337	        rbtree_t *t = rb_create(NULL);
338	        assert(t);
339	        rbnode_t *root = mk_node(t, "m", RB_BLACK);
340	        rbnode_t *right = mk_node(t, "t", RB_BLACK);      /* valid: "t" > "m" */
341	        rbnode_t *deep = mk_node(t, "c", RB_BLACK);       /* valid vs "t": "c" < "t" ... */
342	        right->left = deep;                                /* ...but "c" < "m" violates root's bound */
343	        right->right = t->nil;
344	        deep->left = deep->right = t->nil;
345	        root->right = right;
346	        root->left = t->nil;
347	        root->parent = t->nil;
348	        right->parent = root;
349	        deep->parent = right;
350	        t->root = root;
351	        t->size = 3;
352	        assert(rb_validate(t) != 0);
353	        destroy_and_check_frees(t, 3);
354	        printf("ok - validate_bst_order_deep_right_below_root\n");
355	    }
356	
357	    /* Cases 9-10: black-height mismatch. All nodes BLACK, correct BST
358	     * order, differing only in which side carries an extra black node. */
359	    {
360	        rbtree_t *t = rb_create(NULL);
361	        assert(t);
362	        rbnode_t *root = mk_node(t, "m", RB_BLACK);
363	        rbnode_t *left = mk_node(t, "b", RB_BLACK);
364	        left->left = left->right = t->nil;
365	        root->left = left;
366	        root->right = t->nil; /* one black shorter than the left path */
367	        root->parent = t->nil;
368	        left->parent = root;
369	        t->root = root;
370	        t->size = 2;
371	        assert(rb_validate(t) != 0);
372	        destroy_and_check_frees(t, 2);
373	        printf("ok - validate_black_height_left_heavy\n");
374	    }
375	    {
376	        rbtree_t *t = rb_create(NULL);
377	        assert(t);
378	        rbnode_t *root = mk_node(t, "m", RB_BLACK);
379	        rbnode_t *right = mk_node(t, "v", RB_BLACK);
380	        right->left = right->right = t->nil;
381	        root->right = right;
382	        root->left = t->nil; /* one black shorter than the right path */
383	        root->parent = t->nil;
384	        right->parent = root;
385	        t->root = root;
386	        t->size = 2;
387	        assert(rb_validate(t) != 0);
388	        destroy_and_check_frees(t, 2);
389	        printf("ok - validate_black_height_right_heavy\n");
390	    }
391	
392	    /* Case 11: root color. A single red root is valid BST order (only one
393	     * node), has no red-red violation (no children to conflict with), and
394	     * has equal (zero-length) black-height on both sides -- the only broken
395	     * rule is that the root itself must be black. */
396	    {
397	        rbtree_t *t = rb_create(NULL);
398	        assert(t);
399	        rbnode_t *root = mk_node(t, "m", RB_RED);
400	        root->left = root->right = t->nil;
401	        root->parent = t->nil;
402	        t->root = root;
403	        t->size = 1;
404	        assert(rb_validate(t) != 0);
405	        destroy_and_check_frees(t, 1);
406	        printf("ok - validate_root_must_be_black\n");
407	    }
408	}
409	
410	typedef struct {
411	    const char *name;
412	    const char *key;
413	    void *value;
414	    int fail_at;           /* 0 = no injected malloc failure */
415	    int expect_ok;         /* expect rb_insert to return 0 */
416	    int expect_free_count; /* rb_free calls during the faulted insert; -1 = n/a */
417	} insert_case_t;
418	
419	/* Cases 1-3: baseline success, and injected failure on each of
420	 * rb_insert's internal allocations. Order-agnostic about which
421	 * allocation (node struct vs. key copy) fail_at hits -- the header's
422	 * -1 contract must hold identically either way.
423	 *
424	 * expect_free_count mirrors create_cases' reasoning: fail_at=1 fails on the
425	 * very first rb_malloc call (the node struct), before anything else is
426	 * allocated, so cleanup frees nothing (0); fail_at=2 fails on the second call
427	 * (the key copy) after the node struct already succeeded, so cleanup frees
428	 * exactly that one allocation (1). */
429	static const insert_case_t insert_cases[] = {
430	    { "insert_into_empty_success", "alpha", "alpha-value", 0, 1, -1 },
431	    { "insert_fails_first_alloc",  "beta",  "beta-value",  1, 0,  0 },
432	    { "insert_fails_second_alloc", "gamma", "gamma-value", 2, 0,  1 },
433	};
434	
435	static void test_rb_insert(void)
436	{
437	    size_t n = sizeof insert_cases / sizeof insert_cases[0];
438	    /* invariant: each iteration gets a fresh tree, so a case's outcome
439	     * never depends on a prior case's inserts. */
440	    for (size_t i = 0; i < n; i++) {
441	        const insert_case_t *c = &insert_cases[i];
442	        rbtree_t *t = rb_create(NULL);
443	        assert(t);
444	
445	        if (c->fail_at)
446	            fault_malloc_arm(c->fail_at);
447	        int rc = rb_insert(t, c->key, c->value);
448	        if (c->fail_at) {
449	            assert(fault_malloc_free_count() == c->expect_free_count);
450	            fault_malloc_disarm();
451	        }
452	
453	        assert((rc == 0) == c->expect_ok);
454	        assert(rb_size(t) == (size_t)(c->expect_ok ? 1 : 0));
455	        assert(rb_find(t, c->key) == (c->expect_ok ? c->value : NULL));
456	
457	        rb_destroy(t);
458	        printf("ok - %s\n", c->name);
459	    }
460	
461	    /* Case 4: on allocation failure the tree must not call value_free,
462	     * and the caller must retain sole ownership of value. */
463	    {
464	        rbtree_t *t = rb_create(track_free);
465	        assert(t);
466	        for (int fail_at = 1; fail_at <= 2; fail_at++) {
467	            reset_tracking();
468	            char *v = malloc(8);
469	            assert(v);
470	            strcpy(v, "owned");
471	
472	            fault_malloc_arm(fail_at);
473	            int rc = rb_insert(t, "delta", v);
474	            fault_malloc_disarm();
475	
476	            assert(rc == -1);
477	            assert(!was_freed(v));
478	            assert(rb_size(t) == 0);
479	            free(v);   /* caller still owns it; must not double-free */
480	        }
481	        rb_destroy(t);
482	        printf("ok - insert_failure_value_not_consumed\n");
483	    }
484	
485	    /* Case 5: overwriting an existing key frees the old value via
486	     * value_free, keeps size unchanged, and matches by key content (two
487	     * distinct buffers with identical content, not the same pointer). */
488	    {
489	        rbtree_t *t = rb_create(track_free);
490	        assert(t);
491	        reset_tracking();
492	
493	        char key_first[] = "dup";
494	        char key_second[] = "dup";
495	        char *old_value = malloc(8);
496	        char *new_value = malloc(8);
497	        assert(old_value && new_value);
498	        strcpy(old_value, "old");
499	        strcpy(new_value, "new");
500	
501	        assert(rb_insert(t, key_first, old_value) == 0);
502	        assert(rb_insert(t, key_second, new_value) == 0);
503	
504	        assert(rb_size(t) == 1);
505	        assert(was_freed(old_value));
506	        assert(free_occurrences(old_value) == 1); /* not freed twice */
507	        assert(!was_freed(new_value));
508	        assert(rb_find(t, "dup") == new_value);
509	
510	        /* A second overwrite of the same key, armed so the very first
511	         * rb_malloc call would fail: overwriting an existing key must not
512	         * allocate a new node or key copy (the key is already stored), so a
513	         * correct rb_insert makes zero rb_malloc/rb_free calls here and
514	         * still returns 0 despite the arming. An implementation that always
515	         * allocates a fresh node on every insert (even for a duplicate key)
516	         * would either fail here or leak the discarded new node/key. */
517	        int since = freed_count;   /* old_value's slot may get reused below */
518	        char *third_value = malloc(8);
519	        assert(third_value);
520	        strcpy(third_value, "third");
521	        fault_malloc_arm(1);
522	        int rc = rb_insert(t, "dup", third_value);
523	        assert(fault_malloc_free_count() == 0);
524	        fault_malloc_disarm();
525	        assert(rc == 0);
526	
527	        assert(rb_size(t) == 1);
528	        assert(free_occurrences_since(new_value, since) == 1); /* freed once, not twice */
529	        assert(!was_freed_since(third_value, since));
530	        assert(rb_find(t, "dup") == third_value);
531	
532	        /* A couple more surviving entries, so destroy has to walk multiple
533	         * nodes, not just the one left over from the overwrites. */
534	        char *extra1 = malloc(8);
535	        char *extra2 = malloc(8);
536	        assert(extra1 && extra2);
537	        strcpy(extra1, "extra1");
538	        strcpy(extra2, "extra2");
539	        assert(rb_insert(t, "extra-key-1", extra1) == 0);
540	        assert(rb_insert(t, "extra-key-2", extra2) == 0);
541	
542	        /* The repeated overwrite must have updated the existing node in
543	         * place, not left a stale second "dup" node behind: exactly 3
544	         * distinct keys should be visible to both validate and foreach. */
545	        assert(rb_validate(t) == 0);
546	        collect_ctx_t after_overwrite = {0};
547	        rb_foreach(t, collect_cb, &after_overwrite);
548	        assert(after_overwrite.n == 3);
549	
550	        rb_destroy(t);
551	        /* rb_destroy must run value_free on every value still owned by the
552	         * tree, not just the ones already freed by the earlier overwrites. */
