1193	        rbnode_t *successor = mk_node(t, "w", RB_BLACK);
1194	        rbnode_t *successorRightChild = mk_node(t, "u", RB_BLACK);
1195	        rbnode_t *targetRightRight = mk_node(t, "y", RB_BLACK);
1196	
1197	        root->left = sibling; root->right = target;
1198	        root->parent = t->nil;
1199	        sibling->parent = root;
1200	        target->parent = root;
1201	        target->left = targetLeft; target->right = targetRight;
1202	        targetLeft->parent = target;
1203	        targetRight->parent = target;
1204	        targetRight->left = successor; targetRight->right = targetRightRight;
1205	        successor->parent = targetRight;
1206	        targetRightRight->parent = targetRight;
1207	        successor->left = t->nil; successor->right = successorRightChild;
