1216	
1217	        assert(rb_size(t) == 7);
1218	        assert(root->right == successor);
1219	        assert(successor->parent == root);
1220	        assert(successor->left == targetLeft && targetLeft->parent == successor);
1221	        assert(successor->right == targetRight && targetRight->parent == successor);
1222	        assert(targetRight->left == successorRightChild);
1223	        assert(successorRightChild->parent == targetRight);
1224	        assert(targetRight->right == targetRightRight);
1225	        assert(targetRightRight->parent == targetRight);
1226	
1227	        destroy_and_check_frees(t, 7);
1228	        printf("ok - delete_two_children_successor_is_deep\n");
1229	    }
