1231	    /* Case 9: end-to-end sanity check against a tree assembled through the
1232	     * public API (real fixup shapes it, not a hand-built fixture),
1233	     * deleting several keys of differing shapes in sequence and confirming
1234	     * size, findability, in-order structure, and value ownership all stay
1235	     * consistent -- not just the pointer-level mechanics cases 4-8 pin
1236	     * down. */
1237	    {
1238	        rbtree_t *t = rb_create(track_free);
1239	        assert(t);
1240	        reset_tracking();
1241	
1242	        static const char *keys[] = { "m", "f", "t", "d", "h", "p", "s", "v", "b" };
1243	        size_t n = sizeof keys / sizeof keys[0];
1244	        void *values[9];
1245	        for (size_t i = 0; i < n; i++) {
1246	            values[i] = malloc(8);
1247	            assert(values[i]);
1248	            strcpy(values[i], keys[i]);
1249	            assert(rb_insert(t, keys[i], values[i]) == 0);
1250	        }
1251	        assert(rb_size(t) == n);
1252	
1253	        static const char *to_delete[] = { "b", "h", "t" };
1254	        for (size_t i = 0; i < sizeof to_delete / sizeof to_delete[0]; i++) {
1255	            void *deleted_value = rb_find(t, to_delete[i]);
1256	            assert(deleted_value != NULL);
1257	            assert(rb_delete(t, to_delete[i]) == 0);
1258	            assert(rb_find(t, to_delete[i]) == NULL);
1259	            assert(was_freed(deleted_value));
1260	            assert(free_occurrences(deleted_value) == 1);
1261	        }
1262	
1263	        assert(rb_size(t) == n - 3);
1264	
1265	        collect_ctx_t collected = {0};
1266	        rb_foreach(t, collect_cb, &collected);
1267	        assert(collected.n == (int)(n - 3));
1268	        /* invariant: in-order traversal is still strictly ascending;
1269	         * deletion must never leave BST ordering broken. */
1270	        for (int i = 0; i + 1 < collected.n; i++)
1271	            assert(strcmp(collected.keys[i], collected.keys[i + 1]) < 0);
1272	
1273	        for (size_t i = 0; i < n; i++) {
1274	            int deleted = 0;
1275	            for (size_t j = 0; j < sizeof to_delete / sizeof to_delete[0]; j++)
1276	                if (strcmp(keys[i], to_delete[j]) == 0) deleted = 1;
1277	            if (!deleted)
1278	                assert(rb_find(t, keys[i]) == values[i]);
1279	        }
1280	
1281	        rb_destroy(t);
1282	        /* rb_destroy must free value_free on every value still owned -- the
1283	         * 3 already deleted plus the 6 remaining. */
1284	        assert(freed_count == (int)n);
1285	        printf("ok - delete_end_to_end_mixed_shapes\n");
1286	    }
1287	}
