1333	    rbnode_t *nephewFar = mk_node(t, "x", RB_BLACK);
1334	    root->left = target; root->right = sibling;
1335	    root->parent = t->nil;
1336	    target->parent = root; sibling->parent = root;
1337	    sibling->left = nephewNear; sibling->right = nephewFar;
1338	    nephewNear->parent = sibling; nephewFar->parent = sibling;
1339	    t->root = root;
