1432	    left->parent = root; right->parent = root;
1433	    left->left = leftLeft; left->right = leftRight;
1434	    leftLeft->parent = left; leftRight->parent = left;
1435	    right->left = successor; right->right = rightRight;
1436	    successor->parent = right; rightRight->parent = right;
