1470	    { "delete_red_leaf",                   build_red_leaf,                   "d", 1, verify_red_leaf },
1471	    { "delete_black_leaf_red_sibling",      build_black_leaf_red_sibling,     "f", 4, verify_black_leaf_red_sibling },
1472	    { "delete_two_children_black_successor", build_two_children_black_successor, "d", 6, verify_two_children_black_successor },
