1476	static void test_rb_delete_fixup(void)
1477	{
1478	    size_t n = sizeof delete_fixup_cases / sizeof delete_fixup_cases[0];
1479	    /* invariant: each iteration gets a fresh, independently-validated
1480	     * fixture, so a case's outcome never depends on a prior case. */
1481	    for (size_t i = 0; i < n; i++) {
1482	        const delete_fixup_case_t *c = &delete_fixup_cases[i];
1483	        rbtree_t *t = c->build();
