1	#ifndef RBTREE_H
2	#define RBTREE_H
3	#include <stddef.h>
4	typedef struct rbtree rbtree_t;
5	typedef void (*rb_value_free_fn)(void *value);
6	/* Returns NULL on allocation failure.
7	* value_free may be NULL (values not owned). */
8	rbtree_t *rb_create(rb_value_free_fn value_free);
9	/* Copies key (tree owns the copy).
10	* Takes ownership of value ONLY on success.
11	* Overwriting an existing key frees the old value via value_free.
12	* Returns 0 on success, -1 on allocation failure (tree unchanged, value NOT
13	* consumed; caller still owns it). */
14	int rb_insert(rbtree_t *t, const char *key, void *value);
15	/* Returns the value, or NULL if absent. Tree retains ownership. */
16	void *rb_find(const rbtree_t *t, const char *key);
17	/* Removes key; frees the key copy and the value.
18	* Returns 0, or -1 if absent. */
19	int rb_delete(rbtree_t *t, const char *key);
20	size_t rb_size(const rbtree_t *t);
